(() => {
  'use strict';
  const canvas = document.querySelector('#game');
  const ctx = canvas.getContext('2d');
  const W = 960, H = 540, FLOOR = 454;
  const levels = [
    {name:'FERNWOOD TRAIL', biome:'forest', sky:['#8bd6c3','#d6e8aa'], ground:'#426f53', accent:'#f7cc63', width:2600, spawn:70, exit:2490,
