      platforms:[[0,454,350],[420,454,250],[760,454,250],[1090,454,260],[1430,454,240],[1760,454,260],[2110,454,270],[2470,454,630],[190,350,120],[450,300,110],[620,360,100],[810,310,110],[980,360,100],[1160,295,110],[1350,345,100],[1530,290,110],[1710,350,100],[1900,300,120],[2090,350,100],[2290,290,120],[2490,345,100],[2680,285,130]],
      coins:[[225,311],[490,261],[660,321],[850,271],[1020,321],[1200,256],[1390,306],[1570,251],[1750,311],[1945,261],[2130,311],[2335,251],[2530,306],[2720,246],[2780,246],[2840,410]],hazards:[[275,432,56,22],[500,432,55,22],[850,432,60,22],[1200,432,58,22],[1550,432,55,22],[1850,432,64,22],[2200,432,56,22],[2630,432,60,22]],enemies:[[470,420,570],[810,420,940],[1140,420,1290],[1480,420,1620],[1810,420,1940],[2150,420,2300],[2530,420,2750]]}
  ];
  const keys = {left:false,right:false,jump:false};
  const player = {x:70,y:400,vx:0,vy:0,w:27,h:37,onGround:false,face:1,invuln:0};
  let levelIndex=0, score=0, health=3, state='title', camera=0, coins=[], enemies=[], particles=[], jumpWasDown=false, lastTime=0, elapsed=0;
  let audioCtx=null, soundOn=true, musicTimer=null, musicStep=0;
  const level=()=>levels[levelIndex];
  function initLevel(){const l=level();player.x=l.spawn;player.y=FLOOR-player.h;player.vx=player.vy=0;camera=0;coins=l.coins.map(([x,y])=>({x,y,taken:false,phase:Math.random()*6}));enemies=l.enemies.map(([min,maxX,i])=>({x:min,y:FLOOR-28,w:31,h:25,min,max: maxX,dir:1,speed:45+levelIndex*11,alive:true,phase:Math.random()*4}));particles=[];}
  function startGame(){score=0;health=3;levelIndex=0;initLevel();state='playing';audioStart();}
  function nextLevel(){levelIndex++;if(levelIndex>=levels.length){state='won';playTone(784,.14,'sine');setTimeout(()=>playTone(988,.24,'sine'),120);return;}initLevel();}
  function audioStart(){if(!soundOn)return;try{audioCtx ||= new (window.AudioContext||window.webkitAudioContext)();if(audioCtx.state==='suspended')audioCtx.resume();if(!musicTimer){musicTimer=setInterval(()=>{if(state!=='playing'||!soundOn)return;const notes=[261.63,329.63,392,329.63,293.66,349.23,440,349.23];playTone(notes[musicStep++%notes.length],.22,'sine',.035);},360);}}catch(e){}}
  function playTone(freq,duration=.12,type='sine',volume=.1){if(!soundOn)return;try{audioCtx ||= new (window.AudioContext||window.webkitAudioContext)();const osc=audioCtx.createOscillator(),gain=audioCtx.createGain();osc.type=type;osc.frequency.value=freq;gain.gain.setValueAtTime(volume,audioCtx.currentTime);gain.gain.exponentialRampToValueAtTime(.001,audioCtx.currentTime+duration);osc.connect(gain);gain.connect(audioCtx.destination);osc.start();osc.stop(audioCtx.currentTime+duration);}catch(e){}}
  function setSound(on){soundOn=on;document.querySelector('#soundIcon').textContent=on?'♫':'♪';document.querySelector('#soundLabel').textContent=on?'SOUND ON':'SOUND OFF';if(on)audioStart();}
  document.querySelector('#soundToggle').addEventListener('click',()=>setSound(!soundOn));
  window.addEventListener('keydown',e=>{const k=e.key.toLowerCase();if(['arrowleft','arrowright','arrowup',' ','a','d','w','enter'].includes(k))e.preventDefault();if(k==='arrowleft'||k==='a')keys.left=true;if(k==='arrowright'||k==='d')keys.right=true;if(k==='arrowup'||k==='w'||k===' ')keys.jump=true;if((k==='enter'||k===' ')&&state!=='playing'){if(state==='title'||state==='over'||state==='won')startGame();else if(state==='leveldone')nextLevel();}});
  window.addEventListener('keyup',e=>{const k=e.key.toLowerCase();if(k==='arrowleft'||k==='a')keys.left=false;if(k==='arrowright'||k==='d')keys.right=false;if(k==='arrowup'||k==='w'||k===' ')keys.jump=false;});
  document.querySelectorAll('[data-control]').forEach(btn=>{const control=btn.dataset.control;const down=e=>{e.preventDefault();keys[control]=true;btn.classList.add('pressed');if(state!=='playing'&&(state==='title'||state==='over'||state==='won'))startGame();};const up=e=>{e.preventDefault();keys[control]=false;btn.classList.remove('pressed');};btn.addEventListener('pointerdown',down);['pointerup','pointercancel','pointerleave'].forEach(ev=>btn.addEventListener(ev,up));});
  canvas.addEventListener('pointerdown',()=>{if(state==='title'||state==='over'||state==='won')startGame();else if(state==='leveldone')nextLevel();});
  function overlaps(a,b){return a.x<b.x+b.w&&a.x+a.w>b.x&&a.y<b.y+b.h&&a.y+a.h>b.y;}
  function burst(x,y,color,n=8){for(let i=0;i<n;i++)particles.push({x,y,vx:(Math.random()-.5)*180,vy:-Math.random()*150-25,life:.45+Math.random()*.4,color,size:3+Math.random()*4});}
  function hurt(){if(player.invuln>0)return;health--;player.invuln=1.5;player.vy=-310;player.vx=-player.face*180;playTone(130,.24,'sawtooth',.09);burst(player.x+13,player.y+18,'#ff7381',10);if(health<=0){state='over';playTone(110,.45,'triangle');}}
  function update(dt){elapsed+=dt;if(state!=='playing')return;const l=level();const speed=245;player.vx=(keys.right?1:0)-(keys.left?1:0);if(player.vx)player.face=Math.sign(player.vx);player.vx*=speed;
    if(keys.jump&&!jumpWasDown&&player.onGround){player.vy=-570;player.onGround=false;playTone(430,.08,'sine',.055);}jumpWasDown=keys.jump;
    player.vy=Math.min(player.vy+1500*dt,800);const oldY=player.y;player.x=Math.max(0,Math.min(l.width-player.w,player.x+player.vx*dt));player.y+=player.vy*dt;player.onGround=false;
    for(const [x,y,w] of l.platforms){if(player.x+player.w>x&&player.x<x+w&&player.vy>=0&&oldY+player.h<=y+5&&player.y+player.h>=y){player.y=y-player.h;player.vy=0;player.onGround=true;}}
    if(player.y>H+100){hurt();player.y=FLOOR-player.h;player.vy=0;}
    if(player.invuln>0)player.invuln-=dt;
    l.hazards.forEach(([x,y,w,h])=>{if(overlaps(player,{x,y:y+4,w,h:h-4}))hurt();});
    for(const c of coins){if(!c.taken&&overlaps(player,{x:c.x-12,y:c.y-15,w:24,h:30})){c.taken=true;score+=10;playTone(740,.1,'sine',.07);burst(c.x,c.y,'#ffe27b',6);}}
    enemies.forEach(e=>{if(!e.alive)return;e.x+=e.dir*e.speed*dt;if(e.x<e.min||e.x+e.w>e.max){e.dir*=-1;e.x=Math.max(e.min,Math.min(e.max-e.w,e.x));}e.phase+=dt*6;if(overlaps(player,e)){if(player.vy>80&&oldY+player.h<e.y+12){e.alive=false;player.vy=-370;score+=25;playTone(560,.12,'square',.05);burst(e.x+15,e.y,'#ffb08c',8);}else hurt();}});
    particles=particles.filter(p=>p.life>0);particles.forEach(p=>{p.life-=dt;p.x+=p.vx*dt;p.y+=p.vy*dt;p.vy+=380*dt;});
    if(player.x+player.w>=l.exit){score+=50;playTone(660,.15);if(levelIndex===levels.length-1)state='won';else state='leveldone';}
    camera=Math.max(0,Math.min(l.width-W,player.x-W*.36));
  }
  function rounded(x,y,w,h,r,fill){ctx.fillStyle=fill;ctx.beginPath();ctx.roundRect(x,y,w,h,r);ctx.fill();}
  function drawBackground(){const l=level(),theme=l.biome;const grad=ctx.createLinearGradient(0,0,0,H);grad.addColorStop(0,l.sky[0]);grad.addColorStop(1,l.sky[1]);ctx.fillStyle=grad;ctx.fillRect(0,0,W,H);
    if(theme==='forest'){ctx.fillStyle='#fff3c15c';ctx.beginPath();ctx.arc(756,108,52,0,Math.PI*2);ctx.fill();ctx.fillStyle='#fff2bf';ctx.beginPath();ctx.arc(756,108,29,0,Math.PI*2);ctx.fill();for(let i=0;i<9;i++){const x=((i*210-camera*.2)%1150+1150)%1150-80;const h=130+(i*47)%110;ctx.fillStyle=i%2?'#77ae8d':'#6aa58a';ctx.beginPath();ctx.moveTo(x,390);ctx.lineTo(x+55,390-h);ctx.lineTo(x+120,390);ctx.fill();ctx.fillStyle='#84c5a1';ctx.beginPath();ctx.moveTo(x+26,340);ctx.lineTo(x+55,390-h);ctx.lineTo(x+88,340);ctx.fill();}}
    else if(theme==='mountain'){ctx.fillStyle='#fff1cc';ctx.beginPath();ctx.arc(758,102,34,0,7);ctx.fill();for(let i=0;i<7;i++){const x=((i*250-camera*.16)%1250+1250)%1250-100;const h=170+(i*59)%150;ctx.fillStyle=i%2?'#d18b70':'#ba806b';ctx.beginPath();ctx.moveTo(x-40,420);ctx.lineTo(x+90,420-h);ctx.lineTo(x+230,420);ctx.fill();ctx.fillStyle='#f6dcb1';ctx.beginPath();ctx.moveTo(x+55,420-h+45);ctx.lineTo(x+90,420-h);ctx.lineTo(x+126,420-h+48);ctx.lineTo(x+104,420-h+36);ctx.lineTo(x+90,420-h+52);ctx.lineTo(x+76,420-h+33);ctx.fill();}}
    else{ctx.fillStyle='#a5b6eb';ctx.globalAlpha=.5;ctx.beginPath();ctx.arc(750,106,38,0,7);ctx.fill();ctx.globalAlpha=1;for(let i=0;i<22;i++){let x=((i*83-camera*.09)%1030+1030)%1030,y=42+(i*71)%250;ctx.fillStyle=i%3?'#d4d7ff':'#8cf1dc';ctx.globalAlpha=.3+((i%4)*.13);ctx.beginPath();ctx.arc(x,y,1.5+(i%3),0,7);ctx.fill();}ctx.globalAlpha=1;}
    const layerColor=theme==='forest'?'#78ad84':theme==='mountain'?'#b97d6b':'#303b67';ctx.fillStyle=layerColor;ctx.globalAlpha=.38;ctx.beginPath();ctx.moveTo(0,420);for(let x=0;x<=W+40;x+=40){const y=365+Math.sin((x+camera*.3)/105)*20+Math.cos((x+camera*.17)/63)*11;ctx.lineTo(x,y);}ctx.lineTo(W,H);ctx.lineTo(0,H);ctx.fill();ctx.globalAlpha=1;
  }

